test('browser: lost create response is retried with the same idempotency context',async t=>{
 const f=await knowledgeFixture(t),browser=await chromium.launch({headless:true});t.after(()=>browser.close());const page=await browser.newPage();await page.goto(f.app.listeningOrigin+'/product/');await page.getByLabel('账号',{exact:true}).fill('synthetic-admin');await page.getByLabel('密码',{exact:true}).fill('synthetic-test-pass');await page.getByRole('button',{name:'登录知识库',exact:true}).click();await expect(page.getByRole('heading',{name:'让制度成为可核验的知识'})).toBeVisible();await page.getByRole('button',{name:/知识导入/}).click();await page.getByLabel('选择文件').setInputFiles({name:'idem.md',mimeType:'text/markdown',buffer:Buffer.from('Idempotent browser import\n')});await page.getByRole('button',{name:'下一步'}).click();await page.getByLabel('来源标题 #1').fill('浏览器幂等');await page.getByLabel('制度编号 #1').fill('IDEM-BROWSER');await page.getByLabel('来源版本 #1').fill('1');await page.getByRole('button',{name:'下一步'}).click();
 let first=true,createCalls=0;await page.route('**/knowledge.imports.create.v1',async route=>{createCalls++;const response=await route.fetch();if(first){first=false;await route.abort();}else await route.fulfill({response});});await page.getByRole('button',{name:'提交导入'}).click();await expect(page.getByRole('heading',{name:'待核对的原提交'})).toBeVisible();await page.unroute('**/knowledge.imports.create.v1');await page.getByRole('button',{name:'核对原提交结果'}).click();await expect(page.locator('table').first()).toContainText('idem.md');assert.equal((await f.pool.query("SELECT count(DISTINCT b.id)::int n FROM knowledge_import_batches b JOIN knowledge_import_files f ON f.batch_id=b.id WHERE f.policy_code='IDEM-BROWSER'")).rows[0].n,1);assert.equal(createCalls,1);
});

