async function apiUpload(f,bytes,name='batch.md'){
 const {createHash}=await import('node:crypto');const form=new FormData();form.append('metadata',new Blob([JSON.stringify({spaceId:f.spaceId,idempotencyKey:crypto.randomUUID(),filename:name,mediaType:'text/markdown',byteLength:bytes.length,sha256:createHash('sha256').update(bytes).digest('hex')})],{type:'application/json'}));form.append('file',new Blob([bytes],{type:'text/markdown'}),name);const response=await fetch(f.app.listeningOrigin+'/product/api/commands/knowledge.objects.upload.v1',{method:'POST',headers:{authorization:'Bearer '+f.admin.token},body:form});return response.json();
}

