condHash=new URL(page.url()).hash;await page.reload();await expect.poll(async()=>page.locator('main table tbody tr').count(),{timeout:10000}).toBe(1);assert.equal(new URL(page.url()).hash,secondHash);await tabTo(page,'详情');await page.keyboard.press('Enter');await expect(page.getByRole('heading',{name:'批次详情'})).toBeVisible();assert.match(new URL(page.url()).hash,/after=/);await tabTo(page,'返回列表');await page.keyboard.press('Enter');await expect.poll(async()=>page.locator('main table tbody tr').count(),{timeout:10000}).toBe(1);
