test('browser: parsing cancel remains processing; cancelled retry; stale revision conflict',async t=>{
 const f=await knowledgeFixture(t);const mk=async(name,policy,status='failed')=>{const up=await apiUpload(f,Buffer.from(name+'\n'),name);const r=await f.call('knowledge.imports.create.v1',{spaceId:f.spaceId,idempotencyKey:crypto.randomUUID(),files:[{objectRef:up.objectRef,title:name,policyCode:policy,version:'1',validFrom:'2020-01-01T00:00:00Z'}]},f.admin.token);assert.equal(r.status,200);await f.pool.query('UPDATE knowledge_import_files SET status=$2,error_code=$3 WHERE batch_id=$1',[r.data.batch.batchId,status,status==='failed'?'PARSED_FAILED':null]);await f.pool.query('UPDATE knowledge_import_batches SET status=$2,revision=revision+1 WHERE id=$1',[r.data.batch.batchId,status==='parsing'?'parsing':'failed']);return r.data.batch;};
 const parsing=await mk('parsing-cancel.md','PARSE-CANCEL','parsing');const cancelled=await mk('cancelled-retry.md','CANCEL-RETRY','cancelled');const stale=await mk('stale-retry.md','STALE-RETRY','failed');const browser=await chromium.launch({headless:true});t.after(()=>browser.close());const page=await browser.newPage();await page.goto(f.app.listeningOrigin+'/product/');await page.getByLabel('账号',{exact:true}).fill('synthetic-admin');await page.getByLabel('密码',{exact:true}).fill('synthetic-test-pass');await page.getByRole('button',{name:'登录知识库',exact:true}).click();await expect(page.getByRole('heading',{name:'让制度成为可核验的知识'})).toBeVisible();await page.getByRole('button',{name:/知识导入/}).click();await page.getByRole('row').filter({hasText:'parsing-cancel.md'}).getByRole('button',{name:'请求取消'}).click();await expect.poll(async()=>(await f.call('knowledge.imports.get.v1',{spaceId:f.spaceId,batchId:parsing.batchId},f.admin.token)).data.batch.files[0].status,{timeout:5000}).toBe('parsing');assert.equal((await f.pool.query('SELECT cancel_requested FROM knowledge_import_files WHERE batch_id=$1',[parsing.batchId])).rows[0].cancel_requested,true);await f.pool.query("UPDATE knowledge_import_files SET status='cancelled' WHERE batch_id=$1",[parsing.batchId]);await f.pool.query("UPDATE knowledge_import_batches SET status='cancelled',revision=revision+1 WHERE id=$1",[parsing.batchId]);await expect(page.getByRole('row').filter({hasText:'parsing-cancel.md'})).toContainText('cancelled',{timeout:5000});
 await page.getByRole('row').filter({hasText:'cancelled-retry.md'}).getByRole('button',{name:'重试失败文件'}).click();await expect.poll(async()=>(await f.call('knowledge.imports.get.v1',{spaceId:f.spaceId,batchId:cancelled.batchId},f.admin.token)).data.batch.files[0].status,{timeout:5000}).toBe('uploaded');
 const staleRow=page.getByRole('row').filter({hasText:'stale-retry.md'});await f.pool.query('UPDATE knowledge_import_batches SET revision=revision+1 WHERE id=$1',[stale.batchId]);await staleRow.getByRole('button',{name:'重试失败文件'}).click();await expect(page.locator('#notification .error')).toContainText('版本已变化');assert.equal((await f.call('knowledge.imports.get.v1',{spaceId:f.spaceId,batchId:stale.batchId},f.admin.token)).data.batch.status,'failed');
});

test('browser: four terminal states update by poll within three responses',async t=>{
 const f=await knowledgeFixture(t);const mk=async(name,policy,count=1)=>{const ups=[];for(let i=0;i<count;i++)ups.push(await apiUpload(f,Buffer.from(name+'-'+i+'\n'),name+'-'+i+'.md'));const r=await f.call('knowledge.imports.create.v1',{spaceId:f.spaceId,idempotencyKey:crypto.randomUUID(),files:ups.map((u,i)=>({objectRef:u.objectRef,title:name+' '+i,policyCode:policy+(count>1?'-'+(i+1):''),version:'1',validFrom:'2020-01-01T00:00:00Z'}))},f.admin.token);assert.equal(r.status,200,JSON.stringify(r.data));return r.data.batch;};const completed=await mk('dyn-complete.md','DYN-COMP');const partial=await mk('dyn-partial.md','DYN-PART',2);const failed=await mk('dyn-failed.md','DYN-FAIL');const cancelled=await mk('dyn-cancel.md','DYN-CANCEL');const browser=await chromium.launch({headless:true});t.after(()=>browser.close());const page=await browser.newPage();await page.goto(f.app.listeningOrigin+'/product/');await page.getByLabel('账号',{exact:true}).fill('synthetic-admin');await page.getByLabel('密码',{exact:true}).fill('synthetic-test-pass');await page.getByRole('button',{name:'登录知识库',exact:true}).click();await expect(page.getByRole('heading',{name:'让制度成为可核验的知识'})).toBeVisible();let lists=0;await page.route('**/knowledge.imports.list.v1',route=>{lists++;return route.continue();});await page.getByRole('button',{name:/知识导入/}).click();const assertState=async(batch,rowText,fileSql)=>{const before=lists;await f.pool.query(fileSql,[batch.batchId]);await f.pool.query('UPDATE knowledge_import_batches SET status=$2,revision=revision+1 WHERE id=$1',[batch.batchId,rowText]);await expect(page.getByRole('row').filter({hasText:batch.files[0].filename})).toContainText(rowText,{timeout:6000});assert.ok(lists-before<=3,`${rowText} polls ${lists-before}`);};await assertState(completed,'completed',"UPDATE knowledge_import_files SET status='parsed' WHERE batch_id=$1");const partialBefore=lists;await f.pool.query("UPDATE knowledge_import_files SET status='failed',error_code='PARSED_FAILED' WHERE id=(SELECT id FROM knowledge_import_files WHERE batch_id=$1 ORDER BY created_at LIMIT 1)",[partial.batchId]);await f.pool.query("UPDATE knowledge_import_files SET status='parsed' WHERE id=(SELECT id FROM knowledge_import_files WHERE batch_id=$1 ORDER BY created_at DESC LIMIT 1)",[partial.batchId]);await f.pool.query("UPDATE knowledge_import_batches SET status='partial',revision=revision+1 WHERE id=$1",[partial.batchId]);await expect(page.getByRole('row').filter({hasText:partial.files[0].filename})).toContainText('partial',{timeout:6000});assert.ok(lists-partialBefore<=3);await assertState(failed,'failed',"UPDATE knowledge_import_files SET status='failed',error_code='PARSED_FAILED' WHERE batch_id=$1");await assertState(cancelled,'cancelled',"UPDATE knowledge_import_files SET status='cancelled' WHERE batch_id=$1");
});

