async function tabTo(page,text,{shift=false,max=1200}={}){for(let i=0;i<max;i++){const active=await page.evaluate(()=>({text:document.activeElement?.textContent?.trim()??'',tag:document.activeElement?.tagName??''}));if(active.tag==='BUTTON'&&active.text.includes(text))return;await page.keyboard.press(shift?'Shift+Tab':'Tab');}throw new Error('Tab target not reached: '+text);}

async function identityLateScenario(t,{abort=false,suffix='b'}={}){
 const f=await knowledgeFixture(t);const member=await f.member();await f.write('access.bindings.grant.v1',{principalId:member.principalId,roleId:'knowledge-editor',scopeId:f.spaceId,expectedRevision:0});const username='late-identity-'+suffix,password='late-identity-pass-'+suffix;const account=await f.write('identity.accounts.create.v1',{principalId:member.principalId,username,password});assert.equal(account.status,200);
 const aName='a-identity-'+suffix+'.md',bName='b-identity-'+suffix+'.md';const aUp=await apiUpload(f,Buffer.from(aName+'\n'),aName);const a=await f.call('knowledge.imports.create.v1',{spaceId:f.spaceId,idempotencyKey:crypto.randomUUID(),files:[{objectRef:aUp.objectRef,title:'A identity '+suffix,policyCode:'A-ID-'+suffix,version:'1',validFrom:'2020-01-01T00:00:00Z'}]},f.admin.token);const bUp=await apiUpload(f,Buffer.from(bName+'\n'),bName);const b=await f.call('knowledge.imports.create.v1',{spaceId:f.spaceId,idempotencyKey:crypto.randomUUID(),files:[{objectRef:bUp.objectRef,title:'B identity '+suffix,policyCode:'B-ID-'+suffix,version:'1',validFrom:'2020-01-01T00:00:00Z'}]},f.admin.token);assert.equal(a.status,200);assert.equal(b.status,200);
 const browser=await chromium.launch({headless:true});t.after(()=>browser.close());const page=await browser.newPage();await page.goto(f.app.listeningOrigin+'/product/');await page.getByLabel('账号',{exact:true}).fill('synthetic-admin');await page.getByLabel('密码',{exact:true}).fill('synthetic-test-pass');await page.getByRole('button',{name:'登录知识库',exact:true}).click();await expect(page.getByRole('heading',{name:'让制度成为可核验的知识'})).toBeVisible();await page.evaluate(()=>{window.__identityDocumentMarker='same-document'});await page.getByRole('button',{name:/知识导入/}).click();
 let release,started;const began=new Promise(r=>{started=r;});await page.route('**/knowledge.imports.get.v1',async route=>{if(route.request().postDataJSON().batchId===a.data.batch.batchId){const response=await route.fetch();started();await new Promise(r=>{release=async()=>{if(abort)await route.abort();else await route.fulfill({response});r();};});}else await route.continue();});
 await page.getByRole('row').filter({hasText:aName}).getByRole('button',{name:'详情'}).click();await began;await page.getByRole('button',{name:'退出登录',exact:true}).click();await expect(page.getByRole('button',{name:'登录知识库',exact:true})).toBeVisible();const hashLoad=page.waitForResponse(r=>r.url().includes('identity.me.v1'));await page.evaluate(()=>{location.hash='imports';});await hashLoad;await page.getByLabel('账号',{exact:true}).fill(username);await page.getByLabel('密码',{exact:true}).fill(password);await page.getByRole('button',{name:'登录知识库',exact:true}).click();await expect(page.getByRole('button',{name:'退出登录',exact:true})).toBeVisible();await expect(page.getByRole('heading',{name:'知识导入'})).toBeVisible();await page.getByRole('row').filter({hasText:bName}).getByRole('button',{name:'详情'}).click();await expect(page.getByText(b.data.batch.batchId)).toBeVisible();
 const settled=abort?page.waitForEvent('requestfailed',{predicate:r=>r.url().includes('knowledge.imports.get.v1')}):page.waitForResponse(r=>r.url().includes('knowledge.imports.get.v1'));
 await release();await settled;await page.evaluate(()=>new Promise(r=>requestAnimationFrame(()=>r())));
 assert.equal(await page.evaluate(()=>window.__identityDocumentMarker),'same-document');const bHash=new URL(page.url()).hash;assert.ok(bHash.includes(b.data.batch.batchId));assert.ok(!bHash.includes(a.data.batch.batchId));await expect(page.locator('#notification .error')).toHaveCount(0);const detailSection=page.getByRole('heading',{name:'批次详情'}).locator('..');await expect(detailSection).toContainText(b.data.batch.batchId);await expect(detailSection).not.toContainText(aName);
}
